  --se-ink: #071a38;
  --se-muted: #718096;
  --se-line: rgba(7, 26, 56, .11);
  --se-blue: #0877f9;
  --se-blue-deep: #0757b8;
  border: 1px solid rgba(7, 26, 56, .08);
